def orbit(r,c):
 out={(r,c)}
 changed=True
 while changed:
  changed=False
  for x,y in list(out):
   cand={(y,x)}
   if 0<=31-x<30: cand.add((31-x,y))
   if 0<=31-y<30: cand.add((x,31-y))
   for z in cand:
    if z not in out: out.add(z); changed=True
 return out
